from typing import List, Any


def filter_integers(values: List[Any]) -> List[int]:
    """ Filter given list of any python values only for whole numbers, handling numeric-looking values appropriately
    """
    result = []
    for x in values:
        if isinstance(x, int):
            result.append(x)
        elif isinstance(x, float):
            if x == x and x not in (float('inf'), float('-inf')) and x.is_integer():
                result.append(int(x))
        elif isinstance(x, str):
            s = x.strip()
            try:
                result.append(int(s))
            except ValueError:
                try:
                    f = float(s)
                    if f == f and f not in (float('inf'), float('-inf')) and f.is_integer():
                        result.append(int(f))
                except ValueError:
                    pass
    return result
